/**
 * Local-only run of the table layer over real ODT files (never committed).
 * Skipped unless ODT_CORPUS points at a folder of `.odt` files (one level deep).
 *
 *   ODT_CORPUS=E:/github/odt-corpus npm run test -w @genoffice/odt-engine
 *
 * For every file: every table converts without throwing; an unedited
 * write-back is byte-identical; the first table regenerated by the editor
 * without changes writes nothing back; editing one cell of the first table
 * changes only that cell.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { type Block, parseDocx } from '@genoffice/docx-engine'
import { describe, expect, it } from 'vitest'
import type { TableExt } from '../src/table'
import { editorSave, odtToBridge, writeBack } from './helpers/bridge'
import { cellRuns, editRuns, patchCells, regenerate, tableRegistry } from './helpers/table-editor'

const root = process.env.ODT_CORPUS

function corpusFiles(dir: string): string[] {
  const out: string[] = []
  for (const name of readdirSync(dir)) {
    const path = join(dir, name)
    if (statSync(path).isDirectory()) {
      // generated outputs (out-docx2odt …) are not received files
      if (name.startsWith('out-')) continue
      for (const inner of readdirSync(path)) {
        if (inner.toLowerCase().endsWith('.odt')) out.push(join(path, inner))
      }
    } else if (name.toLowerCase().endsWith('.odt')) out.push(path)
  }
  return out.sort()
}

describe.skipIf(!root)('table layer over the real corpus (ODT_CORPUS)', () => {
  it('converts every table, writes nothing unedited, and edits one cell narrowly', async () => {
    const files = corpusFiles(root as string)
    expect(files.length).toBeGreaterThan(0)
    const failures: string[] = []
    const counts = {
      files: files.length,
      tables: 0,
      topLevel: 0,
      framed: 0,
      nested: 0,
      cells: 0,
      covered: 0,
      locked: 0,
      structureLocked: 0,
      unchanged: 0,
      regenerated: 0,
      regenerateAttempted: 0,
      cellEdits: 0,
      cellEditAttempted: 0,
    }
    for (const file of files) {
      try {
        const bytes = new Uint8Array(readFileSync(file))
        const bridge = await odtToBridge(bytes, tableRegistry())
        const ext = (bridge.map.ext.table ?? null) as unknown as TableExt | null
        if (!ext) continue
        counts.tables += ext.tables.length
        counts.topLevel += ext.tables.filter((t) => t.element !== null).length
        counts.framed += ext.tables.filter((t) => t.frame !== null).length
        counts.nested += ext.tables.filter((t) => t.host !== null).length
        counts.locked += ext.protectedCells.length
        counts.structureLocked += ext.tables.filter((t) => t.structureLocked).length
        for (const t of ext.tables)
          for (const row of t.cells)
            for (const c of row) {
              if (c.kind === 'cell') counts.cells++
              else if (c.kind === 'covered') counts.covered++
            }

        const same = await writeBack(bridge, bridge.docx)
        if (same.content !== bridge.doc.contentXml || same.styles !== (bridge.doc.stylesXml ?? ''))
          failures.push(`${file}: an unedited write-back changed the ODT`)
        else counts.unchanged++

        const first = ext.tables.find((t) => t.element !== null)
        if (!first) continue
        const parsed = await parseDocx(bridge.docx)
        const index = parsed.blocks
          .filter((b) => !b.hidden)
          .findIndex((b) => b.docxIndex === first.element)
        const visible = parsed.blocks.filter((b) => !b.hidden)
        const block = visible[index] as Block
        if (!block || block.type !== 'table') {
          failures.push(`${file}: the first table is not a table block in the bridge`)
          continue
        }
        const original = bridge.doc.contentXml

        // regenerated without changes: nothing is written
        counts.regenerateAttempted++
        const regen = await editorSave(bridge.docx, (blocks) =>
          blocks.map((b, i) => (i === index ? regenerate(b, () => {}) : { keep: i })),
        )
        const rw = await writeBack(bridge, regen.bytes)
        if (rw.content === original && rw.rctx.newAutomaticStyles('content.xml').length === 0)
          counts.regenerated++
        else failures.push(`${file}: the first table regenerated unchanged wrote something back`)

        // one cell edited: only that cell changes
        let target: { row: number; col: number; tc: number } | null = null
        for (let r = 0; r < first.rows.length && !target; r++)
          for (let c = 0; c < first.cells[r].length && !target; c++) {
            const cell = first.cells[r][c]
            if (cell.kind !== 'cell' || cell.protected) continue
            if (cell.units.length !== 1 || cell.units[0].kind !== 'p') continue
            const p = bridge.map.paragraphs[cell.units[0].paragraph]
            if (p && p.text.length > 0 && !p.text.endsWith('\f'))
              target = { row: r, col: c, tc: cell.tc }
          }
        if (!target) continue
        counts.cellEditAttempted++
        const t = target
        const { bytes: edited } = await editorSave(bridge.docx, (blocks) =>
          blocks.map((b, i) =>
            i === index
              ? patchCells(b, [
                  {
                    row: t.row,
                    tc: t.tc,
                    paras: [{ runs: editRuns(cellRuns(b, t.row, t.tc), 0, 0, '편집 ') }],
                  },
                ])
              : { keep: i },
          ),
        )
        const wb = await writeBack(bridge, edited)
        let stripped = wb.content
        for (const x of wb.rctx.newAutomaticStyles('content.xml'))
          stripped = stripped.replace(x, '')
        const cell = first.cells[t.row][t.col]
        if (cell.kind !== 'cell') continue
        const head = original.slice(0, cell.start)
        const tail = original.slice(cell.end)
        const middle = stripped.slice(head.length, stripped.length - tail.length)
        const ok =
          stripped.startsWith(head) &&
          stripped.endsWith(tail) &&
          middle.startsWith(original.slice(cell.start, cell.openEnd)) &&
          // the typed space may join following spaces as `<text:s text:c="n"/>`
          middle.includes('편집')
        if (ok) counts.cellEdits++
        else
          failures.push(
            `${file}: editing cell (${t.row},${t.col}) of the first table touched other parts`,
          )
      } catch (err) {
        failures.push(`${file}: threw ${(err as Error).stack}`)
      }
    }
    console.log(`table corpus: ${JSON.stringify(counts)}, failures ${failures.length}`)
    if (failures.length) console.log(failures.join('\n'))
    expect(failures).toEqual([])
  }, 1_800_000)
})
